module permutation_generator (\n    input [4:0] N, A, B,\n    output reg valid,\n    output reg [4:0] perm [0:15]\n);\n    reg found;\n    integer x, i, k;\n    reg [4:0] temp;\n    reg [4:0] x_val, y_val;\n    reg [4:0] address;\n\n    always @(*) begin\n        // Initialize\n        valid = 1'b0;\n        found = 1'b0;\n        x_val = 5'd0;\n        y_val = 5'd0;\n        address = 5'd0;\n        for (i = 0; i < 16; i = i + 1) begin\n            perm[i] = 5'd0;\n        end\n\n        if (N == 5'd0 || N > 5'd16) begin\n            perm[0] = 5'b11111;\n        end else begin\n            // Solve x*A + y*B = N\n            for (x = 0; x <= 16; x = x + 1) begin\n                if (!found) begin\n                    if (x * A <= N) begin\n                        temp = N - (x * A);\n                        if (B != 5'd0 && temp % B == 5'd0) begin\n                            y_val = temp / B;\n                            if (x * A + y_val * B == N) begin\n                                found = 1'b1;\n                                x_val = x[4:0];\n                            end\n                        end\n                    end\n                end\n            end\n\n            valid = found;\n\n            if (found) begin\n                // Build A cycles\n                for (k = 0; k < x_val; k = k + 1) begin\n                    for (i = 0; i < A; i = i + 1) begin\n                        if (i < (A - 1)) begin\n                            perm[address + i] = address + i + 1;\n                        end else begin\n                            perm[address + i] = address;\n                        end\n                    end\n                    address = address + A;\n                end\n                // Build B cycles\n                for (k = 0; k < y_val; k = k + 1) begin\n                    for (i = 0; i < B; i = i + 1) begin\n                        if (i < (B - 1)) begin\n                            perm[address + i] = address + i + 1;\n                        end else begin\n                            perm[address + i] = address;\n                        end\n                    end\n                    address = address + B;\n                end\n            end else begin\n                perm[0] = 5'b11111;\n            end\n        end\n    end\nendmodule